for w in [10,20,40]:
 for h in [5,10,20]:
  rows=[]
  for d in sorted(set().union(*[set(x.index) for x in D.values()])):
   vals=[];ys=[]
   for s,x in D.items():
    if d not in x.index: continue
    j=x.index.get_loc(d)
    if j<w or j+h>=len(x): continue
    ret=x.close.pct_change().iloc[j-w+1:j+1]
