from alphacrafter.sim.utils import (register_hook, get_stock_daily_data,
    get_index_daily_data, get_account_dict, rebalance_to_weights)

U = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Exact current screener ensemble, all directions +1; signals are lagged below.
F = ["miner_1_20280629_stable_volatility_trend_20d", "miner_1_20281116_defensive_relative_lead_20d", "miner_1_20280323_vix_conditioned_efficiency_trend", "miner_3_20290628_residual_momentum_volscaled_20", "miner_3_20280907_downside_asymmetry_quality_30d", "directional_payoff_efficiency_30d", "miner_2_20290503_path_efficiency_30d", "breadth_vol_quality_40d"]
FW = np.array([.18, .16, .14, .14, .12, .10, .08, .08])
_gate = 0

def rank_cs(values, names):
    good = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in U}
    if not good: return out
    for i, (_, s) in enumerate(good): out[s] = (i + 1.) / len(good)
    return out

def make_weights(score, vol, defensive):
    tilt = {s: 1.0 for s in U}
    if defensive:
        # Full investment is retained; defense is diversified across tradable assets.
        tilt.update({"XAU": 1.25, "US10Y": 1.14, "CN10Y": 1.10,
                     "BTC": .88, "ETH": .88, "WTI": .91, "COPPER": .93})
    raw = {s: tilt[s] * (.35 + score[s]) / max(vol.get(s, .02), .008) ** .20 for s in U}
    w, free, left = {s: 0.0 for s in U}, set(U), 1.0
    while free:
        den = sum(max(raw[s], .001) for s in free)
        hit = [s for s in free if left * max(raw[s], .001) / den > .16]
        if not hit:
            for s in free: w[s] = left * max(raw[s], .001) / den
            break
        for s in hit:
            w[s] = .16; left -= .16; free.remove(s)
    z = sum(w.values())
    return {s: w[s] / z for s in U}

@register_hook
def cross_asset_strategy():
    global _gate
    if _gate:
        _gate -= 1
        return
    px, ret, vol = {}, {}, {}
    for s in U:
        d = get_stock_daily_data(symbol=s, days=280)
        if d is None or len(d) < 100: continue
        c = np.asarray(d.sort_values("date")["close"], float)[:-1]  # completed sessions only
        if len(c) >= 80 and np.all(np.isfinite(c)) and np.all(c > 0):
            px[s] = c; ret[s] = c[1:] / c[:-1] - 1.
            vol[s] = max(float(np.std(ret[s][-40:])), .008)
    names = [s for s in U if s in px]
    if len(names) < 12: return
    R = {s: {h: px[s][-1] / px[s][-(h + 1)] - 1. for h in (5, 20, 30, 40, 60)} for s in names}
    breadth = float(np.mean([R[s][20] > 0 for s in names]))
    market20 = R.get("SPX", {20: np.median([R[s][20] for s in names])})[20]
    vix, shock = 0., 0.
    vd = get_index_daily_data(symbol="VIX", days=55)
    if vd is not None and len(vd) >= 23:
        vc = np.asarray(vd.sort_values("date")["close"], float)[:-1]
        if len(vc) >= 22 and np.all(np.isfinite(vc)):
            vix = float(vc[-1]); shock = vix / max(float(np.median(vc[-21:])), 1e-9) - 1.
    defensive = market20 < -.05 or breadth < .40 or np.mean(list(vol.values())) > .022 or vix >= 20 or shock > .15
    peer = np.mean([ret[s][-20:] for s in names], axis=0)
    fs = {s: [0.] * 8 for s in names}
    for s in names:
        med20 = np.median([R[t][20] for t in names if t != s]); med40 = np.median([R[t][40] for t in names if t != s])
        beta = np.cov(ret[s][-20:], peer)[0, 1] / max(np.var(peer), 1e-8)
        residual = (R[s][20] - beta * np.mean([R[t][20] for t in names])) / max(vol[s], .01)
        neg = ret[s][-30:][ret[s][-30:] < 0]
        dn = max(float(np.std(neg)) if len(neg) > 2 else .01, .006)
        # stable trend, defensive lead, VIX-conditioned efficiency, residual momentum,
        # downside asymmetry, directional payoff efficiency, path efficiency, breadth/vol quality.
        pos = ret[s][-30:][ret[s][-30:] > 0]
        payoff = (float(np.mean(pos)) if len(pos) else 0.) / (float(np.mean(np.abs(neg))) if len(neg) else .01)
        fs[s] = [R[s][20] / max(vol[s], .01),
                 R[s][20] - med20 + .35 * (R[s][40] - med40),
                 (R[s][20] / max(vol[s], .01)) * (1.0 if not defensive else .75),
                 residual,
                 (R[s][30] - .7 * max(-R[s][30], 0)) / (1. + dn),
                 np.clip(payoff, -5., 5.),
                 (.35 * R[s][5] + .40 * R[s][20] + .25 * R[s][60]) / max(vol[s], .01) ** .10,
                 (R[s][20] / max(vol[s], .01)) * (1. if breadth >= .45 else .8)]
    rr = [rank_cs({s: fs[s][j] for s in names}, names) for j in range(8)]
    score = {s: sum(FW[j] * rr[j][s] for j in range(8)) for s in U}
    if defensive:
        for s, b in (("XAU", .012), ("US10Y", .009), ("CN10Y", .007)): score[s] += b
        for s in ("BTC", "ETH", "WTI", "COPPER"): score[s] -= .005
    target = make_weights(score, vol, defensive)
    account = get_account_dict(); assets = max(float(account.get("total_assets", 0)), 1.)
